// Paths an agent may call only with a valid agent token (checked in requireAgentToken below).
export const NEEDS_AGENT_TOKEN = [
  "/api/agent/draft",
  "/api/agent/roadmap",
  "/api/agent/archive",
  "/api/agent/import",
];

export function requireAgentToken(path: string, token: string | undefined, expected: string): boolean {
  if (!NEEDS_AGENT_TOKEN.some((p) => path.startsWith(p))) return true;
  return token === expected;
}

import { requireAgentToken } from "./auth.js";
import { exportAll } from "./export.js";

export function route(req, res, cfg) {
  if (!requireAgentToken(req.url, bearer(req), cfg.agentToken)) return deny(res);
  if (req.url.startsWith("/api/agent/export")) return exportAll(res); // every feature, team and person record
  return next(req, res);
}
